export function AiRecommendation({
  title = "{{title}}",
  rationale = "{{rationale}}",
  impact = "{{impact}}",
  accent = "{{accent}}",
  showRationale = {{showRationale}},
}) {
  const badge = {
    low: { background: "transparent", color: "#24143099", border: "1.5px solid #24143033" },
    medium: { background: `color-mix(in srgb, ${accent} 25%, #FAF7F2)`, color: "#241430", border: `1.5px solid ${accent}` },
    high: { background: accent, color: "#241430", border: `1.5px solid ${accent}` },
  }[impact] ?? {};
  return (
    <div style={{ maxWidth: 380, padding: "16px 18px", background: "#FAF7F2", color: "#241430",
      border: "1.5px solid #24143022", borderRadius: 12, boxSizing: "border-box", fontFamily: "system-ui, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10 }}>
        <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>{title}</h3>
        <span style={{ flexShrink: 0, textTransform: "capitalize", fontSize: 11, fontWeight: 700, padding: "0.3em 0.7em",
          borderRadius: 999, whiteSpace: "nowrap", ...badge }}>{impact} impact</span>
      </div>
      {showRationale && <p style={{ margin: "10px 0 0", fontSize: 13, color: "#241430cc" }}>{rationale}</p>}
      <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
        <button type="button" style={{ font: "600 13px system-ui, sans-serif", padding: "7px 16px", borderRadius: 8,
          cursor: "pointer", border: `1.5px solid ${accent}`, background: accent, color: "#241430" }}>Accept</button>
        <button type="button" style={{ font: "600 13px system-ui, sans-serif", padding: "7px 16px", borderRadius: 8,
          cursor: "pointer", border: "1.5px solid #24143033", background: "transparent", color: "#241430" }}>Reject</button>
      </div>
    </div>
  );
}
